local config = {
  ui_story_31190101_1_dialog_content = "Navigator, Navigator!",
  ui_story_31190101_2_dialog_content = "Itu Vice, 'kan? Ada apa?",
  ui_story_31190101_X2_dialog_content = "Ada kejadian penting!",
  ui_story_31190101_3_dialog_content = "Sebuah rambu yang aneh muncul di sepanjang lorong!",
  ui_story_31190101_4_dialog_content = "Hah? Rambu? Rambu macam apa, sih?",
  ui_story_31190101_5_dialog_content = "Anu... Rambu kayu.",
  ui_story_31190101_X5_dialog_content = "Ada simbol Illumina besar sekali di bagian depannya.",
  ui_story_31190101_6_dialog_content = "Lalu terukir kalimat yang berbunyi, <color=#FFB400>\"Sentuh rambu ini jika kau berani menantang orang terkuat di Colossus!\"</color> di bagian belakangnya.",
  ui_story_31190101_7_dialog_content = "Apa jangan-jangan... ada orang di Colossus yang ingin berkelahi?",
  ui_story_31190101_8_dialog_content = "Aku tidak yakin...",
  ui_story_31190101_9_dialog_content = "Tapi, kalau mengingat kejadian yang dulu-dulu, sepertinya ini ulah Illumina!",
  ui_story_31190101_11_dialog_content = "Nih, lihat, 'kan? Sebelah sini...",
  ui_story_31190101_12_dialog_content = "Ya... Aku melihatnya.",
  ui_story_31190101_13_dialog_content = "Apa mungkin ini suatu tantangan dari seorang penghuni Colossus?",
  ui_story_31190101_14_dialog_content = "Sepertinya... tantangan ini akan jadi masalah besar!",
  ui_story_31190101_15_dialog_content = "Kalau sampai terjadi pertempuran di Colossus, siapa yang tahu bakal seberapa parah kerusakannya!",
  ui_story_31190101_16_dialog_content = "Aduh... memikirkan jumlah biaya perbaikan pada fasilitas yang rusak di Colossus saja membuatku pusing tujuh keliling!",
  ui_story_31190101_17_dialog_content = "Navigator, tabungan kita terancam...",
  ui_story_31190101_18_dialog_content = "Vice, coba tenang sedikit, dong...",
  ui_story_31190101_19_dialog_content = "Sudah kucoba! Tapi, serius, deh... Siapa sih yang mau melakukan itu di Colossus!?",
  ui_story_31190101_20_dialog_content = "Belum terjadi apa-apa, Vice. Jangan membayangkan yang tidak-tidak dulu, dong...",
  ui_story_31190101_21_dialog_content = "Ekormu terayun ke mana-mana!",
  ui_story_31190101_22_dialog_content = "Eh... Suara apa itu?",
  ui_story_31190101_23_dialog_content = "Ekormu... menyenggol jatuh rambu kayu itu.",
  ui_story_31190101_24_dialog_content = "Wah, jadi kau rupanya... Kau berani menantang orang terkuat di Colossus—<color=#FFB400>Revy</color>?",
  ui_story_31190101_25_dialog_content = "Aaaah!",
  ui_story_31190101_26_dialog_content = "Ya, kaulah orangnya—Vice—si pemanah berekor panjang, datang kemari untuk menantangku?",
  ui_story_31190101_27_dialog_content = "Tidak, tidak, tidak...",
  ui_story_31190101_28_dialog_content = "Dengar, Revy! Aku tidak mau menantang siapa pun! Ekorku tak sengaja menyenggol rambu itu sampai jatuh. Paham?",
  ui_story_31190101_29_dialog_content = "Eh, tunggu... \"Menantangku\"? Maksudmu, kau yang menaruh rambu ini di sini?",
  ui_story_31190101_30_dialog_content = "Tentu saja.",
  ui_story_31190101_31_dialog_content = "Berarti maksudmu... Kau orang terkuat di Colossus, Revy?",
  ui_story_31190101_32_dialog_content = "Kau juga berpikir begitu, 'kan? Tentu saja! Cara pikir pahlawan memang sama.",
  ui_story_31190101_33_dialog_content = "Ahaha... Jadi, kau menunggu orang datang untuk menantangmu?",
  ui_story_31190101_34_dialog_content = "Iya, dan kau orang pertama yang menyentuh Rambu Kayu Keberanianku.",
  ui_story_31190101_35_dialog_content = "Memang... Tapi, kau langsung muncul begitu aku menyentuhnya, Revy!",
  ui_story_31190101_36_dialog_content = "Benar... Kok kamu tahu bahwa Vice yang menyentuhnya?",
  ui_story_31190101_37_dialog_content = "Apa ada teknologi baru dari Illumina yang tidak kami ketahui?",
  ui_story_31190101_38_dialog_content = "Nah, aku tadi sembunyi di sana, 'kan...? Mengintai dari balik bayangan...",
  ui_story_31190101_39_dialog_content = "Mengintai dari balik bayangan? Maksudmu, dari tadi kau diam-diam mengawasi siapa yang menyentuh rambumu...?",
  ui_story_31190101_40_dialog_content = "Benar... Memangnya sejelas itu, ya?",
  ui_story_31190101_41_dialog_content = "Vice adalah orang pertama yang menyentuh rambu kayuku.",
  ui_story_31190101_42_dialog_content = "Nah, sekarang Vice harus menantangku. Dengan pertempuran ini, ayo kita lihat—siapa yang terkuat!",
  ui_story_31190101_43_dialog_content = "Eh, Revy... Anu... Tadi itu tidak sengaja, kok...",
  ui_story_31190101_44_dialog_content = "Tapi, kamu 'kan tetap menyentuhnya.",
  ui_story_31190101_45_dialog_content = "Hmm... Bagaimana kalau kita tidak usah bertempur dan sepakat bahwa kaulah yang terkuat?",
  ui_story_31190101_46_dialog_content = "Tidak mau! Aku hanya bisa membuktikan bahwa akulah \"Orang Terkuat di Colossus\" dengan pertempuran sampai titik darah penghabisan!",
  ui_story_31190101_47_dialog_content = "Aduh, kenapa aku sampai terlibat dengan hal seperti ini, sih...!?",
  ui_story_31190101_48_dialog_content = "Siap berduel sampai titik darah penghabisan?",
  ui_story_31190101_49_dialog_content = "Dengar, Revy... Bagaimana kalau kauturunkan senjatamu lalu kita bicara baik-baik...?",
  ui_story_31190101_50_dialog_content = "Baiklah.",
  ui_story_31190101_51_dialog_content = "Begini, semua orang yang tinggal di Colossus itu setara. Tak perlu menantang satu sama lain...",
  ui_story_31190101_52_dialog_content = "Selain itu... kita berdua sama-sama Illumina Soldier!",
  ui_story_31190101_53_dialog_content = "Prajurit pun juga harus mengasah keterampilannya, 'kan.",
  ui_story_31190101_54_dialog_content = "Ya, dan itu berlaku dua kali lipat untuk prajurit di garis depan! Kita harus memperkuat diri dengan darah segar dan kobaran api pertempuran!",
  ui_story_31190101_55_dialog_content = "Hah? Maksudmu, kamu ingin menghajarku sampai... berdarah-darah!?",
  ui_story_31190101_56_dialog_content = "Iya.",
  ui_story_31190101_57_dialog_content = "Menurutku sebaiknya simpan saja tenaga kita untuk melawan Eclipsite bersama-sama...",
  ui_story_31190101_58_dialog_content = "Nah, kalau itu baru cara \"memperkuat\" diri yang lebih masuk akal ketimbang duelmu yang konyol... Bagaimana?",
  ui_story_31190101_59_dialog_content = "Yah, mau tak mau harus kuakui bahwa kau ada benarnya, sih... Tapi, menurutku pertempuran kecil yang sportif itu tidak ada salahnya.",
  ui_story_31190101_60_dialog_content = "Hei, kalian... Bagaimana kalau kita istirahat sebentar dan membicarakan ini lagi nanti?",
  ui_story_31190101_61_dialog_content = "Saatnya istirahat! Saatnya istirahat!",
  ui_story_31190101_62_dialog_content = "Pertandingan! Salah! Salah!",
  ui_story_31190101_63_dialog_content = "Pertandingan terkonfirmasi!",
  ui_story_31190101_64_dialog_content = "Salah! Salah! Melakukan perbaikan!",
  ui_story_31190101_65_dialog_content = "Kesalahan mekanisme perbaikan! Kesalahan mekanisme perbaikan!",
  ui_story_31190101_66_dialog_content = "Sial... Ini gara-gara para Firefly itu.",
  ui_story_31190101_67_dialog_content = "Sekarang rekaman dan suara sistemnya malah kacau. Sialan...",
  ui_story_31190101_68_dialog_content = "Bisa diam tidak, sih!? Kepalaku jadi pusing!",
  ui_story_31190101_69_dialog_content = "Navigator! Aku tak bermaksud membuatmu pusing, kok... Kita 'kan hanya sedang berdiskusi. Teman tidak boleh bertengkar!",
  ui_story_31190101_70_dialog_content = "Dengar, aku tidak suka berdebat...",
  ui_story_31190101_71_dialog_content = "Soal bertarung? Aku hanya bilang sebaiknya kita melakukan pertarungan persahabatan. Yah, tapi mungkin ada orang yang menganggapnya keduanya sama saja, sih.",
  ui_story_31190101_72_dialog_content = "Tidak ada bedanya, tahu?! Terutama kalau kau bicara soal bertarung!",
  ui_story_31190101_73_dialog_content = "Hmm? Benarkah? Mungkin... Bukan itu intinya.",
  ui_story_31190101_74_dialog_content = "Lho, yang kumaksud bukan kalian!",
  ui_story_31190101_75_dialog_content = "Kalian! Kalian!",
  ui_story_31190101_76_dialog_content = "(Gawat, nih... Semuanya malah jadi kacau...)",
  ui_story_31190101_77_dialog_content = "(Oh, iya, benar juga!)",
  ui_story_31190101_X77_dialog_content = "(Eh, aku sering pingsan, 'kan? Sebaiknya aku pura-pura pingsan saja agar semua ini selesai!)",
  ui_story_31190101_78_dialog_content = "Vice... Revy... Berhenti berdebat...",
  ui_story_31190101_79_dialog_content = "Aku...",
  ui_story_31190101_80_dialog_content = "Aduh! Navigator! Navigator! Dia pingsan, ya!?",
  ui_story_31190101_81_dialog_content = "Hah...? Keberadaanku yang kuat membuat Navigator kita yang lemah ini pingsan...?",
  ui_story_31190101_82_dialog_content = "<color=#e8d9bb>Anda dibawa kembali ke kamar Anda oleh Vice dan Revy...</color>",
  ui_story_31190101_83_dialog_content = "<color=#e8d9bb>Beberapa jam kemudian...</color>",
  ui_story_31190101_84_dialog_content = "Wow... Ternyata berhasil juga.",
  ui_story_31190101_85_dialog_content = "Aku berhasil mencegah pertumpahan darah di Colossus...",
  ui_story_31190101_86_dialog_content = "Hah? Siapa itu?",
  ui_story_31190101_87_dialog_content = "Ini aku. Kau sudah siuman, ya...",
  ui_story_31190101_88_dialog_content = "Oh... Masuklah.",
  ui_story_31190101_89_dialog_content = "...Sudah merasa baikan?",
  ui_story_31190101_90_dialog_content = "Yah, kurang lebih begitu.",
  ui_story_31190101_91_dialog_content = "Jadi, kau pingsan karena aku ingin mengadakan tantangan dan pertarungan di Colossus... Iya, 'kan?",
  ui_story_31190101_92_option_content = "...Bukan begitu!",
  ui_story_31190101_93_dialog_content = "Yang benar? Tapi, begitu dengar soal pertarungan saja kau langsung pingsan tadi.",
  ui_story_31190101_94_option_content = "Benar.",
  ui_story_31190101_95_dialog_content = "Sudah kuduga.",
  ui_story_31190101_96_dialog_content = "...Yah, aku sudah menyingkirkan rambu kayu itu.",
  ui_story_31190101_97_dialog_content = "Selama aku tidak memulai tantangan lain, kau tak akan pingsan lagi, 'kan?",
  ui_story_31190101_98_dialog_content = "Iya, kamu benar.",
  ui_story_31190101_99_dialog_content = "Hmm. Aku mengerti.",
  ui_story_31190101_100_dialog_content = "Kalau begitu, aku pergi dulu.",
  ui_story_31190101_101_dialog_content = "<color=#e8d9bb>Beberapa hari kemudian.</color>",
  ui_story_31190101_102_dialog_content = "*alarm berbunyi*",
  ui_story_31190101_103_dialog_content = "Apa sekarang masih jam makan siang...? Atau barusan aku hanya bermimpi mendengar alarmnya berbunyi...?",
  ui_story_31190101_104_dialog_content = "Cahaya Firefly...? Berarti...",
  ui_story_31190101_105_dialog_content = "Ini bukan mimpi!",
  ui_story_31190101_106_dialog_content = "Ada apa ini?",
  ui_story_31190101_107_dialog_content = "Lounge! Gagal memperbaiki samsak! Lounge! Gagal memperbaiki samsak!",
  ui_story_31190101_108_dialog_content = "Fiuh... Sepertinya Soroz masih utuh...",
  ui_story_31190101_109_dialog_content = "Sebaiknya aku memeriksa Lounge.",
  ui_story_31190101_110_dialog_content = "<color=#e8d9bb>Terdengar suara gaduh dari Lounge.</color>",
  ui_story_31190101_111_dialog_content = "Nah, sekarang waktunya sesi interaktif <color=#FFB400>Eclipsite Annihilation Assembly</color>.",
  ui_story_31190101_112_dialog_content = "Hoi—jelaskan cara menyingkirkan Eclipsite, dan peragakan metode penggunaan samsak.",
  ui_story_31190101_113_dialog_content = "Seperti yang kutunjukkan tadi.",
  ui_story_31190101_114_dialog_content = "Ha! Aku pernah melindas Eclipsite dengan truk berlapis baja!",
  ui_story_31190101_X114_dialog_content = "Seperti ini!",
  ui_story_31190101_115_dialog_content = "Pernah mencium aroma jus Eclipsite? Itu tidak cocok untuk pengecut!",
  ui_story_31190101_116_dialog_content = "Samsak——ledakan pasir tumpah ruah... Berusaha memperbaiki! Berusaha memperbaiki——",
  ui_story_31190101_117_dialog_content = "Biasanya aku menggunakan sihir untuk menyingkirkan mereka.",
  ui_story_31190101_118_dialog_content = "Mereka memejamkan mata dan tewas. Menurutku itu metode paling sederhana dan praktis.",
  ui_story_31190101_X118_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_31190101_119_dialog_content = "Samsak terbuka! Berusaha memperbaiki! Berusaha memperbaiki!",
  ui_story_31190101_120_dialog_content = "Eclipsite? Tinggal ambil pistol dan tarik pelatuknya hingga berbunyi... \"klik\". Heh...",
  ui_story_31190101_121_dialog_content = "Samsak——Kebocoran pasir terdeteksi! Berusaha memperbaiki! Berusaha memperbaiki!",
  ui_story_31190101_122_dialog_content = "Dulu, aku dan teman-temanku sering menerjang gerombolan Eclipsite dan berhasil selamat tanpa terluka sedikit pun...",
  ui_story_31190101_123_dialog_content = "Kami hajar mereka dengan cepat sampai-sampai para makhluk itu tak langsung menyadari apa yang terjadi! Lalu mereka lari kocar-kacir...",
  ui_story_31190101_124_dialog_content = "Samsak berhasil diperbaiki! Tidak ada kebocoran——",
  ui_story_31190101_X124_dialog_content = "Ha.",
  ui_story_31190101_125_dialog_content = "Samsak——Samsak hancur! Kegagalan! Perbaikan gagal! Perbaikan gagal!",
  ui_story_31190101_126_dialog_content = "Aku membuat catatan resmi dari semua kontribusi kalian di setiap pertemuan. Kalian sudah membagikan 265 cara berbeda untuk menyingkirkan Eclipsite.",
  ui_story_31190101_127_dialog_content = "Sekarang kalian kelihatan puas. Ayo kita lanjutkan kolaborasi ini lain kali.",
  ui_story_31190101_128_dialog_content = "Dengan ini, kunyatakan bahwa pertemuan ini... selesai!",
  ui_story_31190101_129_dialog_content = "Wah, untung mereka hanya semacam... berdiskusi...",
  ui_story_31190101_130_dialog_content = "<color=#e8d9bb>Setelah kembali ke kamarmu...</color>",
  ui_story_31190101_131_dialog_content = "Dua puluh samsak rusak.",
  ui_story_31190101_132_dialog_content = "<anim type=Shake><size=45>Dua puluh samsak rusak!!!</size></anim>",
  ui_story_31190101_133_dialog_content = "Iya, iya, aku tahu...",
  ui_story_31190101_134_dialog_content = "Seharusnya kau senang karena hanya itu yang rusak!",
  ui_story_31190101_135_dialog_content = "Ah, sudahlah. Selama mereka tidak bertarung di Colossus, kalau hanya dua puluh samsak yang rusak saja aku tidak keberatan.",
  ui_story_31190101_136_dialog_content = "<color=#e8d9bb>Keesokan harinya.</color>",
  ui_story_31190101_137_dialog_content = "Anu... Kau di sana?",
  ui_story_31190101_138_dialog_content = "Aku di sini. Ada apa, Revy?",
  ui_story_31190101_139_dialog_content = "Firefly-mu berkali-kali menyiarkan... perbuatan kami... di Colossus kemarin.",
  ui_story_31190101_140_dialog_content = "Perbuatan?",
  ui_story_31190101_141_dialog_content = "...Samsak yang rusak itu.",
  ui_story_31190101_142_dialog_content = "...Aku minta maaf.",
  ui_story_31190101_143_dialog_content = "Sepertinya kami merusakkan dua puluh samsak kemarin. Kalau saja Vice tidak menghentikan kami, kerusakannya akan lebih besar.",
  ui_story_31190101_144_dialog_content = "Itu salah. Permintaan maaf yang seperti itu tidak cukup. Sebelum kemari, aku sudah menanyakan cara meminta maaf yang tulus kepada Vice.",
  ui_story_31190101_145_dialog_content = "Ehem... Begini, aku, Revy, benar-benar meminta maaf atas kerugian besar yang kusebabkan padamu dan Colossus kemarin, Navigator.",
  ui_story_31190101_146_dialog_content = "Tidak perlu minta maaf begitu...",
  ui_story_31190101_147_dialog_content = "Bukan masalah besar, kok. Selama kau tidak bertarung di Colossus, aku tidak keberatan.",
  ui_story_31190101_148_dialog_content = "Sungguh?",
  ui_story_31190101_149_dialog_content = "Maksudmu... kamu tidak marah?",
  ui_story_31190101_150_option_content = "Tentu saja.",
  ui_story_31190101_151_dialog_content = "Rupanya kamu tidak salah paham padaku!",
  ui_story_31190101_152_option_content = "Sejujurnya, aku sedikit marah...",
  ui_story_31190101_153_dialog_content = "Kalau begitu, silakan lampiaskan saja amarahmu itu padaku.",
  ui_story_31190101_154_dialog_content = "Kami tidak bermaksud merusak Colossus. Aku hanya ingin membuktikan...",
  ui_story_31190101_155_dialog_content = "Aku tahu, kok.",
  ui_story_31190101_156_dialog_content = "Untuk membuktikan bahwa aku memang orang terkuat di Colossus...",
  ui_story_31190101_157_dialog_content = "...Bagaimanapun juga, teman tidak boleh saling bertarung... terutama di Colossus!",
  ui_story_31190101_158_dialog_content = "Aku akan... mematuhi perintahmu.",
  ui_story_31190101_159_dialog_content = "<color=#e8d9bb>Satu hari kemudian, saat Soroz akan mendarat...</color>",
  ui_story_31190101_160_dialog_content = "Hah? Apa itu yang di pintu?",
  ui_story_31190101_161_dialog_content = "Tertanda—Master dari Alter-Blade, Mechanical Overlord, dan Colossus' Ultimate Vanguard—Revy.",
  ui_story_31190101_162_dialog_content = "Apa ini...",
  ui_story_31190101_163_dialog_content = "Aduh, menjijikkan! Bau busuk apa itu!?",
  ui_story_31190101_164_dialog_content = "Ada catatan di dalamnya...",
  ui_story_31190101_165_dialog_content = "\"Karena aku tidak boleh menantang temanku, dan tidak boleh bertarung di Colossus...\"",
  ui_story_31190101_166_dialog_content = "\"Setelah kita mendarat, aku akan menantang pemimpin teman-temanku—sang Caelestite!\"",
  ui_story_31190101_167_dialog_content = "Aduh, rasanya bau ini bisa membuatku pingsan lagi...",
  ui_story_31190101_X167_dialog_content = "...",
  ui_story_31190101_168_dialog_content = "Setelah melihat tantangan Revy, sepertinya lebih baik aku pingsan saja, deh...",
  ui_story_31190601_1_dialog_content = "Berkat Anda, kami dapat mengidentifikasi perampok dalam waktu singkat.",
  ui_story_31190601_2_dialog_content = "Bantuan Anda sangat dihargai. Yakinlah, dia akan mendapatkan hukuman yang pantas dia dapatkan...",
  ui_story_31190601_3_dialog_content = "Saya hanya melakukan apa yang saya rasa harus saya lakukan. Saya selalu senang membantu!",
  ui_story_31190601_4_dialog_content = "<color=#e8d9bb>Buk, Buk, Buk!</color>",
  ui_story_31190601_5_dialog_content = "Hah? Suara apa itu?",
  ui_story_31190601_6_dialog_content = "Kedengarannya seperti seseorang—tidak, seperti sepasang orang yang baru saja jatuh ke tanah.",
  ui_story_31190601_7_dialog_content = "Ah, pasti anak baru lagi. Aku bersumpah, sejak dia tiba di sini, sepertinya tidak pernah berhenti...",
  ui_story_31190601_8_dialog_content = "Anak baru\"? Saya tidak berpikir seorang anak bisa membuat suara seperti itu ...",
  ui_story_31190601_9_dialog_content = "Heh, saya juga tidak akan percaya jika saya tidak melihatnya sendiri.",
  ui_story_31190601_10_dialog_content = "Pada hari dia tiba, saya pergi ke selnya untuk mengantarkan makanannya. Pada saat itu, semuanya tampak sangat normal.",
  ui_story_31190601_11_dialog_content = "Tetapi ketika saya kembali untuk mengambil nampannya, semua orang di sel itu telah dikalahkan oleh bocah gila itu.",
  ui_story_31190601_12_dialog_content = "Dan saat mereka terbaring tak sadarkan diri di seluruh lantai, dia duduk di samping, memakan makanan mereka seolah-olah tidak ada yang terjadi.",
  ui_story_31190601_13_dialog_content = "Huh... Kami sudah memindahkannya 16 kali sekarang. Kalau terus begini, satu-satunya tempat untuknya adalah kurungan isolasi.",
  ui_story_31190601_14_dialog_content = "Tunggu, maksudmu... Seorang gadis kecil bertarung dan menang melawan semua narapidana di 15 sel penjara?!",
  ui_story_31190601_15_dialog_content = "(Gadis kecil yang sangat kuat yang suka berkelahi... Aku punya firasat buruk tentang ini...)",
  ui_story_31190601_16_dialog_content = "Itu benar, itulah mengapa aku harus benar-benar melihat apa yang terjadi kali ini.",
  ui_story_31190601_17_dialog_content = "Maaf, tapi Anda harus melihat diri Anda keluar. Anda tahu di mana pintu keluarnya, kan?",
  ui_story_31190601_18_dialog_content = "Er, jika tidak terlalu merepotkan... Bolehkah aku ikut denganmu?",
  ui_story_31190601_19_dialog_content = "Dengan saya?",
  ui_story_31190601_20_dialog_content = "T-Tolong jangan salah paham! Aku janji aku tidak apa-apa!",
  ui_story_31190601_21_dialog_content = "Hanya saja aku punya perasaan aku mungkin bisa membantumu dengan ini.",
  ui_story_31190601_22_dialog_content = "Yah... Hancurkan dirimu, nak.",
  ui_story_31190601_23_dialog_content = "Terutama karena Anda sudah banyak membantu kami. Jika ada yang bertanya, saya hanya akan mengatakan kami mengambil jalan memutar cepat di jalan keluar.",
  ui_story_31190601_24_dialog_content = "Tapi tidak ada bisnis yang lucu, mengerti? Kalau tidak, itu kepalaku di talenan.",
  ui_story_31190601_25_dialog_content = "Siap!",
  ui_story_31190601_26_dialog_content = "Jangan bilang tidak ada sel lain yang tersisa?",
  ui_story_31190601_27_dialog_content = "Ini adalah kekecewaan yang lebih besar dari yang kukira... Bisakah aku menjadi lebih kuat?",
  ui_story_31190601_28_dialog_content = "(Tunggu, itu terdengar seperti...)",
  ui_story_31190601_29_dialog_content = "Revy?!",
  ui_story_31190601_30_dialog_content = "Hah? Oh, hei PlayerName! Apakah Anda ditangkap juga?",
  ui_story_31190601_31_dialog_content = "Kalian berdua saling kenal?",
  ui_story_31190601_32_dialog_content = "Ya... Sedikit, sebenarnya...",
  ui_story_31190601_33_dialog_content = "Anda tahu, saya selalu menganggap Anda sebagai tipe pahlawan yang baik-baik, seperti karakter utama dalam buku komik. Tidak pernah berpikir saya akan melihat Anda di penjara suatu hari nanti!",
  ui_story_31190601_34_dialog_content = "Tapi karena kau di sini... Kurasa aku tidak punya pilihan selain menjatuhkanmu juga.",
  ui_story_31190601_35_dialog_content = "Aku tidak ditangkap sama sekali! Aku datang untuk mengidentifikasi tersangka perampokan.",
  ui_story_31190601_36_dialog_content = "Tunggu sebentar. Apakah Anda memukuli semua narapidana di sini... sendirian?",
  ui_story_31190601_37_dialog_content = "Benar sekali!",
  ui_story_31190601_38_dialog_content = "Jadi penjaga itu tidak bercanda... Kamu benar-benar memukuli setiap tahanan di seluruh penjara sendirian?!",
  ui_story_31190601_39_dialog_content = "Ya, tapi orang-orang ini tidak semenyenangkan yang ada di lima belas sel terakhir. Saya bahkan hampir tidak menyentuh mereka sebelum mereka jatuh langsung ke tanah!",
  ui_story_31190601_40_dialog_content = "Luar biasa... Tidak seorang pun di penjara Umbraton yang bau ini tahu bagaimana cara bertarung!",
  ui_story_31190601_41_dialog_content = "T-Fasilitas ini hanya dimaksudkan untuk menampung penjahat kecil! Tapi menilai dari dua hari terakhir, kurasa ini juga bukan tempat yang tepat untukmu...",
  ui_story_31190601_42_dialog_content = "Hah? Kau membiarkanku pergi, kalau begitu?",
  ui_story_31190601_43_dialog_content = "Dalam mimpimu! Hanya dalam dua hari, Anda berhasil mengalahkan setiap narapidana di tempat ini!",
  ui_story_31190601_44_dialog_content = "Pada awalnya, saya pikir itu karena Anda tidak cocok dengan para tahanan di sel pertama. Tapi ternyata, Anda memiliki tulang untuk memilih dengan setiap orang di seluruh tempat sialan!",
  ui_story_31190601_45_dialog_content = "Jika Anda tidak menemukan alasan yang lebih baik untuk semua pertempuran ini, saya tidak punya pilihan selain memindahkan Anda ke sel isolasi.",
  ui_story_31190601_46_dialog_content = "...",
  ui_story_31190601_47_dialog_content = "Kesempatan terakhir, Nak—kenapa kamu berkelahi dengan semua teman satu selmu?",
  ui_story_31190601_48_dialog_content = "(Dia terus melirikku... Apakah ada sesuatu yang tidak bisa dia katakan pada penjaga?)",
  ui_story_31190601_49_dialog_content = "S-Tuan? Bisakah kita punya waktu untuk berbicara secara pribadi?",
  ui_story_31190601_50_dialog_content = "Aku hanya butuh sepuluh menit. Percayalah padaku!",
  ui_story_31190601_51_dialog_content = "Anda dapat mengawasi kami dari sisi lain sel. Saya berjanji tidak akan melanggar hukum apa pun!",
  ui_story_31190601_52_dialog_content = "... Baik. Aku harus menelepon dokter penjara di sini.",
  ui_story_31190601_53_dialog_content = "Ada penjaga yang ditempatkan di pintu juga, jadi jangan coba-coba kabur.",
  ui_story_31190601_54_dialog_content = "Terima kasih atas kepercayaannya, Pak.",
  ui_story_31190601_55_dialog_content = "Penjaga itu sudah lama pergi, Revy. Saya pikir Anda dapat berbicara dengan bebas sekarang.",
  ui_story_31190601_56_dialog_content = "A-Tentang apa? Saya tidak tahu apa yang Anda bicarakan ...",
  ui_story_31190601_57_dialog_content = "Saya sedang berbicara tentang alasan Anda memulai perkelahian di penjara!",
  ui_story_31190601_58_dialog_content = "Mereka akan mengunci Anda sendirian jika Anda tidak mengatakan yang sebenarnya!",
  ui_story_31190601_59_dialog_content = "... Baik, tapi saya hanya memberitahu Anda.",
  ui_story_31190601_60_dialog_content = "Karena itu sangat penting bagimu... Aku hanya <color=#FFB400>bermain dengan aturan penjara</color>, itu saja.",
  ui_story_31190601_61_dialog_content = "\"Aturan penjara\"...?",
  ui_story_31190601_62_dialog_content = "Iya!",
  ui_story_31190601_63_dialog_content = "Lihat, tidak ada toko di penjara. Anda tidak bisa hanya membeli apa pun yang Anda inginkan.",
  ui_story_31190601_64_dialog_content = "Jika Anda benar-benar menginginkan sesuatu di sini, Anda mengambilnya dari orang lain... Dengan paksa, jika diperlukan.",
  ui_story_31190601_65_dialog_content = "Dan itulah aturan penjara, singkatnya.",
  ui_story_31190601_66_dialog_content = "Jika itu masalahnya, lalu mengapa kamu tidak memberi tahu penjaga saja? Aku yakin dia sudah melihat semuanya sekarang.",
  ui_story_31190601_67_dialog_content = "Sekarang bukan waktu yang tepat untuk memberitahunya. Saya masih sangat frustrasi dan kesal.",
  ui_story_31190601_68_dialog_content = "Untuk alasan apa? Revy, Anda telah mengirim semua orang ke sini terkapar. Apakah Anda tidak mendapatkan apa yang Anda inginkan?",
  ui_story_31190601_69_dialog_content = "Itu saja! Saya mengalahkan mereka semua, setiap orang! Itulah yang sangat mengganggu.",
  ui_story_31190601_70_dialog_content = "Tapi target saya dan alasan saya untuk masuk penjara di tempat pertama bahkan belum datang! Saya masih belum mendapatkan untuk apa saya datang!",
  ui_story_31190601_71_dialog_content = "<size=45>Anda mengirim diri Anda ke penjara hanya agar Anda bisa mengambil sesuatu?!</size>",
  ui_story_31190601_72_dialog_content = "Apa yang begitu penting sehingga Anda rela masuk penjara untuk itu?!",
  ui_story_31190601_73_dialog_content = "Nah, karena itu Anda, saya kira saya bisa memberi tahu Anda, PlayerName.",
  ui_story_31190601_74_dialog_content = "Ini adalah harta karun legendaris, yang dikejar banyak orang. Harta karun yang bahkan telah mengalahkan prajurit terhebat dalam sejarah!",
  ui_story_31190601_75_dialog_content = "Hanya satu hirupan akan membuat kulit kepala siapa pun tertusuk dan terbakar ...",
  ui_story_31190601_76_dialog_content = "Dan hanya satu rasa akan membuat seluruh kepala Anda menjadi merah dan berkeringat ...",
  ui_story_31190601_77_dialog_content = "Tapi meski begitu, orang tidak bisa menahan kekuatannya dan akan terus memakannya seperti sekelompok pecandu gila...",
  ui_story_31190601_78_dialog_content = "T-Tunggu sebentar!",
  ui_story_31190601_79_dialog_content = "Apa yang Anda gambarkan terdengar terlalu berbahaya...",
  ui_story_31190601_80_dialog_content = "Apakah Anda yakin Anda tahu apa yang Anda lakukan?!",
  ui_story_31190601_81_dialog_content = "Apa yang kamu katakan? Saya sedang berbicara tentang <color=#FFB400>Saus Panas Super Blazing</color>!",
  ui_story_31190601_82_dialog_content = "Hah? Anda sedang berbicara tentang saus pedas?",
  ui_story_31190601_83_dialog_content = "Apa lagi yang bisa? Hanya ada satu hal yang cocok dengan deskripsi saya, dan itu adalah Saus Panas Super Blazing.",
  ui_story_31190601_84_dialog_content = "Anda lihat, \"pedas\" bukan hanya rasa. Ini semacam rasa sakit.",
  ui_story_31190601_85_dialog_content = "Makan makanan pedas membuat tubuh Anda terus-menerus memproduksi adrenalin dan endorfin lainnya, yang pada gilirannya membuat Anda merasakan kegembiraan dan kepuasan.",
  ui_story_31190601_86_dialog_content = "Dengan hal ini, Anda akan dapat terus bergerak maju bahkan setelah lidah Anda benar-benar mati rasa!",
  ui_story_31190601_87_dialog_content = "Ah, semakin aku membicarakannya, semakin aku ingin mencicipi kelezatannya yang mengejutkan... Aku sangat menginginkannya!",
  ui_story_31190601_88_dialog_content = "Jadi alasanmu memukuli semua tahanan ini... hanya untuk mendapatkan saus pedas spesial?",
  ui_story_31190601_89_dialog_content = "Pertama-tama, itu disebut <color=#FFB400>Saus Panas Super Blazing</color>.",
  ui_story_31190601_90_dialog_content = "Kedua, saya baru saja memberi tahu Anda bahwa banyak orang hanya pernah bermimpi memilikinya! Saya akan melakukan apa saja hanya untuk mendapatkan beberapa!",
  ui_story_31190601_91_dialog_content = "Maksudku, aku percaya kamu disana... Lagi pula, kamu bahkan rela masuk penjara karena itu. Aku ingin tahu apakah Gram pernah mendengar tentang—",
  ui_story_31190601_92_dialog_content = "<size=45>Berhenti!!!</size>",
  ui_story_31190601_93_dialog_content = "Dia, uh... tidak tahu aku di sini.",
  ui_story_31190601_94_dialog_content = "Saya sedang membantu Gram membeli beberapa bahan di Umbraton ketika saya mendengar beberapa orang berbicara tentang saus pedas.",
  ui_story_31190601_95_dialog_content = "Saya tidak bisa menahan diri, jadi saya berjalan untuk mendengar lebih banyak. Saya tidak pernah berharap mendengar mereka menyebutkan <color=#FFB400>Saus Panas Super Blazing</color> meskipun.",
  ui_story_31190601_96_dialog_content = "Salah satu dari mereka mengatakan bahwa itu dilayani hampir secara eksklusif di penjara.",
  ui_story_31190601_97_dialog_content = "Dengan rasa yang kuat, hanya satu tetes yang Anda butuhkan untuk semangkuk makanan utuh. Awalnya, itu dirancang khusus sebagai bumbu makanan penjara terbaik.",
  ui_story_31190601_98_dialog_content = "Sebagai hasil dari rasanya yang luar biasa, itu menjadi bentuk mata uang keras di dalam sistem penjara.",
  ui_story_31190601_99_dialog_content = "Hanya dengan satu botol <color=#FFB400>Saus Panas Super Blazing</color>, seseorang bisa menukarnya dengan apa pun yang mereka inginkan di penjara.",
  ui_story_31190601_100_dialog_content = "Tetapi bahkan setelah mengalahkan semua tahanan ini, saya masih belum melihat setetes barang pun ...",
  ui_story_31190601_101_dialog_content = "Sudah sepuluh menit! \"Kunjungan\" kecil Anda sudah berakhir sekarang.",
  ui_story_31190601_102_dialog_content = "Anda tepat waktu, Pak!",
  ui_story_31190601_103_dialog_content = "Saya tidak dapat menemukan apa yang saya inginkan di sini, jadi Anda bisa membiarkan saya pergi sekarang.",
  ui_story_31190601_104_dialog_content = "Yah, mengingat betapa kecilnya kejahatanmu sejak awal, aku bisa saja membiarkanmu pergi...",
  ui_story_31190601_105_dialog_content = "Tapi setelah melihatmu memukuli setiap tahanan yang kita miliki di tempat ini, aku khawatir kamu harus bertahan lebih lama lagi.",
  ui_story_31190601_106_dialog_content = "<size=45>Apa?! Apakah kamu bercanda?!</size>",
  ui_story_31190601_107_dialog_content = "Sekarang kita berada di subjek, apa sebenarnya yang Anda lakukan untuk dijebloskan ke penjara, Revy?",
  ui_story_31190601_108_dialog_content = "Aku tidak ingin melanggar hukum atau apa pun... Aku hanya ingin masuk ke sini.",
  ui_story_31190601_109_dialog_content = "Jadi saya berdiri di depan seorang petugas patroli, menarik rambu lalu lintas dari tanah, dan kemudian memasangnya kembali ke tempatnya beberapa kali.",
  ui_story_31190601_110_dialog_content = "Setelah itu, mereka menuduh saya melakukan perusakan properti umum dan melemparkan saya ke sini.",
  ui_story_31190601_111_dialog_content = "Saya kira itu menjelaskan banyak tentang sifat kejahatan para narapidana di sini ...",
  ui_story_31190601_112_dialog_content = "Aku harus membawa semua tahanan ini ke bangsal medis. Malam ini, Anda harus duduk di sini sendirian dan memikirkan apa yang telah Anda lakukan.",
  ui_story_31190601_113_dialog_content = "T-Tunggu, Pak. Karena penasaran, pernahkah Anda mendengar... saus pedas super pedas?",
  ui_story_31190601_114_dialog_content = "Ini disebut <color=#FFB400>Saus Panas Super Blazing</color>!",
  ui_story_31190601_115_dialog_content = "Y-Ya, itu. Kudengar rasanya luar biasa dan digunakan sebagai semacam mata uang keras di penjara.",
  ui_story_31190601_116_dialog_content = "Saus apa, sekarang? Saya belum pernah mendengar hal semacam itu.",
  ui_story_31190601_117_dialog_content = "Selain itu, penjara Umbraton menggunakan daging kaleng sebagai bentuk mata uang keras mereka.",
  ui_story_31190601_118_dialog_content = "<size=45>Apa?!?</size>",
  ui_story_31190601_119_dialog_content = "Tapi bagaimana ini bisa terjadi...? Bagaimana mungkin penjara tidak memiliki saus pedas legendarisku...?",
  ui_story_31190601_120_dialog_content = "... Apakah kamu baik-baik saja, Revy?",
  ui_story_31190601_121_dialog_content = "Anda terlihat seperti jiwa Anda telah meninggalkan Anda ...",
  ui_story_31190601_122_dialog_content = "aku... aku akan baik-baik saja...",
  ui_story_31190601_123_dialog_content = "PlayerName... Aku benar-benar bisa pergi untuk beberapa masakan rumah Gram sekarang ...",
  ui_story_31190601_124_option_content = "Jangan khawatir. Saya akan melihat apa yang bisa saya lakukan untuk mengeluarkan Anda!",
  ui_story_31190601_125_dialog_content = "Eh, Pak? Anda mengatakan bahwa kejahatannya cukup ringan untuk membiarkannya pergi, bukan?",
  ui_story_31190601_126_dialog_content = "Juga, pertengkaran kecilnya dengan tahanan lain harus dianggap sebagai bagian dari \"aturan penjara\" yang tak terucapkan di sini.",
  ui_story_31190601_127_dialog_content = "Apakah ada kemungkinan Anda bisa...",
  ui_story_31190601_128_dialog_content = "Tidak. Tapi aku akan memberitahumu segera setelah dia bebas pergi.",
  ui_story_31190601_129_dialog_content = "Aku mengerti... Maaf, Revy. Ini di luar kendaliku.",
  ui_story_31190601_130_option_content = "Maaf, aku tidak bisa membantumu keluar.",
  ui_story_31190601_131_dialog_content = "Maksudku, penjahat atau bukan, kau menyerang semua orang ini...",
  ui_story_31190601_132_dialog_content = "T-Tapi jangan khawatir! Saya akan pastikan untuk membawakan Anda beberapa makanan Gram segera setelah mereka membiarkan Anda keluar!",
  ui_story_31190601_133_dialog_content = "Huh... Aku tahu itu. Kurasa kau benar-benar tidak bisa mengandalkan siapa pun selain dirimu sendiri, ya?",
  ui_story_31190601_134_dialog_content = "Untung saya mulai mempersiapkan hari ini bertahun-tahun yang lalu.",
  ui_story_31190601_135_dialog_content = "Orang seperti apa yang bersiap untuk berada di penjara suatu hari nanti?",
  ui_story_31190601_136_dialog_content = "Itu tidak penting. Yang penting adalah bahwa saya telah menghabiskan lima tahun terakhir mempersiapkan diri jika saya mendapati diri saya perlu keluar dari penjara.",
  ui_story_31190601_137_dialog_content = "Sepertinya ini saatnya untuk menggunakan gerakan \"itu\" dengan baik...",
  ui_story_31190601_138_dialog_content = "<color=#e8d9bb>Duk, duk, duk…</color>",
  ui_story_31190601_139_dialog_content = "Eh, Revi? Apa yang kamu lakukan di sudut sana?",
  ui_story_31190601_140_dialog_content = "Kedengarannya sangat mengerikan seperti ... <size=45>A-Apakah kamu menggali terowongan?!</size>",
  ui_story_31190601_141_dialog_content = "Ssst!!! Pertahankan, ya?!",
  ui_story_31190601_142_dialog_content = "Saya melakukan matematika. Jika saya mulai menggali sekarang, saya harus kembali ke Kota Gannon dalam waktu kurang dari sepuluh tahun.",
  ui_story_31190601_143_dialog_content = "Setelah saya akhirnya menggali jalan menuju kebebasan, bahkan kekuatan di atas akan terkesan!",
  ui_story_31190601_144_dialog_content = "Dan ketika hari yang mulia itu tiba, aku akan mengangkat pedang yang membantuku melarikan diri, melihat ke dalam hujan lebat, dan berteriak ke langit—",
  ui_story_31190601_145_dialog_content = "Tapi penjaganya masih di sini, Revy. Dia telah melihatmu menggali selama ini.",
  ui_story_31190601_146_dialog_content = "Eh?",
  ui_story_31190601_147_dialog_content = "Juga... Aku cukup yakin dia mendengar semua yang baru saja kau katakan.",
  ui_story_31190601_148_dialog_content = "Menggali, untuk semua yang saya pedulikan.",
  ui_story_31190601_149_dialog_content = "Ada banyak tahanan di sini yang ingin menggali jalan keluar. Anda bukan yang pertama, dan Anda pasti tidak akan menjadi yang terakhir.",
  ui_story_31190601_150_dialog_content = "Namun, kebanyakan dari mereka menyerah setelah sekitar tiga hari. Terlama saya melihat seorang tahanan terus berjalan adalah seminggu, dan bahkan kemudian... \"Terowongan\" yang mereka gali hanyalah lubang sedalam satu meter.",
  ui_story_31190601_151_dialog_content = "Wow... Apakah mereka menyerah karena tugas yang terlalu sulit?",
  ui_story_31190601_152_dialog_content = "Maksudku, tidak benar-benar. Seperti yang saya katakan, tempat ini hanya dimaksudkan untuk menahan penjahat kecil. Kami biasanya hanya menahan mereka hingga seminggu sebelum kami melepaskannya.",
  ui_story_31190601_153_dialog_content = "Jadi aku terjebak di sini selama seminggu penuh...?",
  ui_story_31190601_154_dialog_content = "Itu tidak perlu. Saya sudah meminta dokumen rilis khusus dari Shadowlord. Anda bisa ikut dengan saya sekarang.",
  ui_story_31190601_155_dialog_content = "semua! Anda datang untuk menyelamatkan saya!",
  ui_story_31190601_156_dialog_content = "Ya! Aku tahu aku tidak ditakdirkan untuk terkurung di tempat seperti ini selamanya!",
  ui_story_31190601_157_dialog_content = "Allura? Apa yang kamu lakukan di sini, dari semua tempat?",
  ui_story_31190601_158_dialog_content = "Kalau kamu benar-benar ingin tahu...",
  ui_story_31190601_159_dialog_content = "<color=#e8d9bb>Dua hari yang lalu</color>",
  ui_story_31190601_160_dialog_content = "Anda butuh sesuatu, Gram? Atau apakah Anda kebetulan menemukan saya barang antik langka di Kota Gannon?",
  ui_story_31190601_161_dialog_content = "Tidak, ini tentang Revy.",
  ui_story_31190601_162_dialog_content = "Revi? Apa yang terjadi?",
  ui_story_31190601_163_dialog_content = "Tidak ada apa-apa! Yah, belum, sih. Aku melihatnya pergi pagi ini, tapi dia berpakaian sangat berbeda dari biasanya.",
  ui_story_31190601_164_dialog_content = "Aku mengikutinya keluar pintu, hanya untuk melihatnya menumpang kereta persediaan menuju Umbraton. Maukah Anda mengawasi anak itu untuk saya?",
  ui_story_31190601_165_dialog_content = "Mengapa tidak datang ke sini sendiri? Apakah Anda tidak penasaran untuk melihat apa yang dia lakukan?",
  ui_story_31190601_166_dialog_content = "Karena dia sendiri tidak memberitahuku, dia tidak ingin aku tahu. Saya bukan tipe orang yang melakukan sesuatu yang tidak perlu.",
  ui_story_31190601_167_dialog_content = "Dia bebas melakukan apapun yang dia mau. Yang aku pedulikan hanyalah memastikan dia aman.",
  ui_story_31190601_168_dialog_content = "Dipahami. Aku akan mengawasinya.",
  ui_story_31190601_169_dialog_content = "Aku melihatmu di Umbraton tepat setelah aku menyelesaikan percakapanku dengan Gram.",
  ui_story_31190601_170_dialog_content = "Jadi kenapa kamu tidak muncul lebih awal?! Saya pikir saya akan terjebak di sini selama seminggu!",
  ui_story_31190601_171_dialog_content = "Sebagai permulaan, saat aku melihatmu mengganggu petugas patroli dengan rambu lalu lintas... Sejujurnya aku ingin berpura-pura tidak mengenalmu.",
  ui_story_31190601_172_dialog_content = "Juga, saya memiliki hal-hal yang jauh lebih mendesak pada saat itu. Saya akan melewatkan kesempatan sekali seumur hidup untuk melihat barang antik yang unik jika saya memutuskan untuk ikut campur dalam aksi kecil Anda.",
  ui_story_31190601_173_dialog_content = "Selain itu, mengingat betapa kecilnya kejahatan Anda, saya pikir mereka hanya akan mengunci Anda selama satu atau dua hari dengan penjahat lain yang sama kecilnya.",
  ui_story_31190601_174_dialog_content = "Itu jauh lebih aman daripada membiarkan Anda mengamuk di jalanan Umbraton, jujur saja. Lagipula, tidak ada seorang pun di penjara ini yang memiliki peluang melawanmu.",
  ui_story_31190601_175_dialog_content = "(Dia berpikir sejauh itu... sejujurnya, dia ikut bertanggung jawab atas situasi ini...)",
  ui_story_31190601_176_dialog_content = "Aku tidak pernah tahu kamu bisa begitu dingin, Allura. Itu menyakitkan!",
  ui_story_31190601_177_dialog_content = "Yah, sebagai orang yang dingin, kurasa aku harus berbalik dan pergi sekarang.",
  ui_story_31190601_178_dialog_content = "T-Tunggu, jangan pergi! Saya salah, sekarang bisakah Anda mengeluarkan saya dari sini? Saya sangat ingin memiliki beberapa makanan Gram sekarang!",
  ui_story_31190601_179_dialog_content = "Yah, aku juga merindukan masakannya...",
  ui_story_31190601_180_dialog_content = "Jika saya membawa Anda kembali ke Kota Gannon, saya bisa meminta makanan sebagai pembayaran untuk pekerjaan kecilnya ini.",
  ui_story_31190601_181_dialog_content = "Aku ikut!",
  ui_story_31190601_182_dialog_content = "Kami sudah lama tidak duduk bersama untuk menikmati salah satu makanan legendaris Gram. Ini benar-benar membawa kembali kenangan akan Dunefire Strike...",
  ui_story_31190601_183_dialog_content = "Hari ini, saya harus mengejar semua makanan yang saya lewatkan beberapa hari terakhir ini!",
  ui_story_31190601_184_dialog_content = "Makanan ini bisa dipasangkan dengan saus super pedas...",
  ui_story_31190601_185_dialog_content = "Revi...",
  ui_story_31190601_186_dialog_content = "Aku tidak akan menyerah begitu saja! Setelah saya makan kenyang, saya akan terus mengejar saus pedas impian saya!",
  ui_story_31190601_187_dialog_content = "<color=#FFB400>Saus Panas Super Blazing</color>... Suatu hari, kamu akan menjadi milikku!",
  ui_story_31190602_1_dialog_content = "Ini adalah uji coba, sekaligus permainan yang tak tertandingi kegembiraannya.",
  ui_story_31190602_2_dialog_content = "Gronru, Tech Officer dari Illumina Federation, secara resmi mengundang kamu untuk berpartisipasi dalam permainan ini.",
  ui_story_31190602_3_dialog_content = "Tidak ada biaya untuk bermain, dan tidak ada formulir yang perlu diisi. Yang perlu Anda lakukan hanyalah memegang teknologi canggih terbaru milik saya, dan Anda bahkan bisa mengumpulkan biaya iklan untuk kesulitan Anda.",
  ui_story_31190602_4_dialog_content = "Dengan perangkat ini, kamu akan mampu melindungi yang lemah, serta semua orang di Illumina dan bahkan dunia.",
  ui_story_31190602_5_dialog_content = "Jadi, apa yang kamu tunggu? Ambil tindakan dan bergabunglah dengan Patroli Eclipsite sekarang!",
  ui_story_31190602_6_dialog_content = "Senang kamu ada di sini, Nona Revy.",
  ui_story_31190602_7_dialog_content = "Semoga Anda tidak keberatan saya bertanya, tapi apakah surat itu tidak terasa mencurigakan bagi Anda?",
  ui_story_31190602_8_dialog_content = "Benar! Tapi jika aku bisa melindungi yang lemah seperti pahlawan sungguhan, aku siap untuk memainkan permainan ini.",
  ui_story_31190602_9_dialog_content = "Lalu Anda harus mengganti pakaian dengan busana baru untuk iklan tersebut.",
  ui_story_31190602_10_dialog_content = "Hah? Pakaian baru?",
  ui_story_31190602_11_dialog_content = "Pakaian ini... Mereka <size=45>benar-benar berat sekali!</size>",
  ui_story_31190602_12_dialog_content = "Rasanya aku tercekik! Bagaimana aku bisa melindungi anak-anak dalam kondisi seperti ini?!",
  ui_story_31190602_13_dialog_content = "Jadi, peran apa yang Anda pikirkan untuk saya? Anda bisa memberi tahu saya, kan?",
  ui_story_31190602_14_dialog_content = "Kamu akan tahu begitu Petugas Gronru tiba di sini!",
  ui_story_31190602_15_dialog_content = "Hoi, PlayerName!",
  ui_story_31190602_16_dialog_content = "Revy? Jadi kamu adalah penampil yang lain, ya?",
  ui_story_31190602_17_dialog_content = "Pakaian itu terlihat sangat keren di dirimu!",
  ui_story_31190602_18_dialog_content = "Benarkah? Karena aku merasa seperti kura-kura yang terjebak di dalam cangkangnya.",
  ui_story_31190602_19_dialog_content = "Mana pakaian baru kamu?",
  ui_story_31190602_20_dialog_content = "Siapa yang tahu? Semuanya tergantung pada Gronru, tampaknya.",
  ui_story_31190602_21_dialog_content = "Hah? Hei, lihat lemari besar di sana! Apakah di situ mereka menyimpan kamera dan barang-barangnya?",
  ui_story_31190602_22_dialog_content = "Tahan! Jangan sentuh Bahan Eksperimental S-Grade milikku dengan tanganmu!",
  ui_story_31190602_23_dialog_content = "Oh, syukurlah! Jika ini berantakan, seluruh iklan akan sia-sia!",
  ui_story_31190602_24_dialog_content = "Ahem! Sepertinya semua orang sudah hadir dan siap!",
  ui_story_31190602_25_dialog_content = "Heheh, sekarang akhirnya saya bisa mengungkapkan penemuan terbaru saya! Usahakan jangan terlalu terkejut!",
  ui_story_31190602_26_dialog_content = "Nikmati Eclipsite Vacuum Cleaner! Jangan ragu untuk melompat dan berteriak sekarang, jika kamu mau!",
  ui_story_31190602_27_dialog_content = "Kalau itu membantuku membunuh Eclipsite dan melindungi yang lemah, itu sudah cukup bagiku!",
  ui_story_31190602_28_dialog_content = "Tunggu, jadi \"teknologi mutakhir terbaru\" kamu itu hanya penyedot debu?!",
  ui_story_31190602_29_dialog_content = "Hei, kau tarik kembali kata-kata itu sekarang juga! Namanya Eclipsite Vacuum Cleaner, terima kasih banyak!",
  ui_story_31190602_30_dialog_content = "Bagaimana Anda bisa begitu tidak tahu?",
  ui_story_31190602_31_dialog_content = "Hei, rasanya cukup enak di tangan! Bagaimana cara menggunakannya?",
  ui_story_31190602_32_dialog_content = "Yang ini telah ditingkatkan untuk menyerupai Alter-Blade-mu. Sedangkan cara menggunakannya, akan kujelaskan tepat sebelum kita mulai menembak.",
  ui_story_31190602_33_dialog_content = "Kalian berdua seharusnya sudah tahu sekarang, kan? Saya ingin kalian menggunakan Vacuum Cleaner Eclipsite untuk membantu saya merekam video promosi!",
  ui_story_31190602_34_dialog_content = "Dan kita hanya berdua sebagai aktor?",
  ui_story_31190602_35_dialog_content = "Yep! Video promosiku tidak memerlukan banyak orang.",
  ui_story_31190602_36_dialog_content = "(Sebenarnya, kalian berdua adalah satu-satunya yang datang... Semua orang lain mengira ini adalah lelucon.)",
  ui_story_31190602_37_dialog_content = "Jadi, siapa yang memerankan tokoh utama?",
  ui_story_31190602_38_dialog_content = "Itu akan menjadi... Revy!",
  ui_story_31190602_39_dialog_content = "Lalu bagaimana dengan saya?",
  ui_story_31190602_40_dialog_content = "Kamu akan memerankan Eclipsite yang menyergap Revy, hanya untuk kemudian dihancurkan total oleh Eclipsite Vacuum Cleaner miliknya.",
  ui_story_31190602_41_dialog_content = "Aku keberatan!",
  ui_story_31190602_42_dialog_content = "Ditolak!",
  ui_story_31190602_43_dialog_content = "Aku baru saja ingat sesuatu, Pak Polisi Gronru. Bukankah kita harus merias Revy sebelum mulai syuting?",
  ui_story_31190602_44_dialog_content = "Serahkan saja itu padaku! Heeheehee, ini pasti akan menyenangkan!",
  ui_story_31190602_45_dialog_content = "Urgh—Rasanya benar-benar aneh.",
  ui_story_31190602_46_dialog_content = "Jangan khawatir! Ini barang paling canggih, meskipun aku tidak tahu apa ini!",
  ui_story_31190602_47_dialog_content = "Saya pikir saya harus menangani ini, Petugas Gronru.",
  ui_story_31190602_48_dialog_content = "Lihat, lubang hidung Revy sekarang penuh dengan makeup.",
  ui_story_31190602_49_dialog_content = "<size=45>Ahhh—Achoo—</size>",
  ui_story_31190602_50_dialog_content = "Tidak mungkin, ini terlalu menyenangkan! Biarkan aku yang melakukannya!",
  ui_story_31190602_51_dialog_content = "Sedikit lagi di sini, sedikit lagi di sana, dan jadi deh!",
  ui_story_31190602_52_dialog_content = "Sempurna! Bahkan kadang-kadang aku sendiri merasa kagum!",
  ui_story_31190602_53_dialog_content = "Hmm, aku rasa kamu harus membiarkan Siobhan mengurus riasan Revy kali ini.",
  ui_story_31190602_54_dialog_content = "<color=#e8d9bb>Setelah makeover kedua, kedua aktor berlatih dialog mereka sebelum belajar cara menggunakan penyedot debu.</color>",
  ui_story_31190602_55_dialog_content = "Tiga, dua, satu, aksi!",
  ui_story_31190602_56_dialog_content = "Aku penasaran seberapa baik kinerja penyedot debu baruku?",
  ui_story_31190602_57_dialog_content = "Wow, sangat kuat. Rasanya seperti... Senjata berperingkat S di level pertama.",
  ui_story_31190602_58_dialog_content = "Garis-garis ini sangat buruk. Kamu yakin ini tidak apa-apa?",
  ui_story_31190602_59_dialog_content = "Tidak bisa dihindari. Petugas Gronru menulisnya sendiri.",
  ui_story_31190602_60_dialog_content = "Saatnya bagianmu!",
  ui_story_31190602_61_dialog_content = "<size=45>Wusss—</size>",
  ui_story_31190602_62_dialog_content = "Eclipsite? Siap-siap mati!",
  ui_story_31190602_63_dialog_content = "Berlututlah di hadapan kehebatan Penyedot Debu Eclipsite-ku!",
  ui_story_31190602_64_dialog_content = "(Uhh, sepertinya aku harus lebih terlibat sedikit lagi.)",
  ui_story_31190602_65_dialog_content = "(Hah? Aku tidak bergerak, jadi kenapa... Kenapa tubuhku mulai...)",
  ui_story_31190602_66_dialog_content = "Aaaahhhh—Ini... Ini akan menyeretku masuk!",
  ui_story_31190602_67_dialog_content = "Waktu habis! Waktu habis! Gronru, potong!",
  ui_story_31190602_68_dialog_content = "Celanaku! Celanaku terseret pergi!",
  ui_story_31190602_69_dialog_content = "Jangan berhenti sekarang! Terus berlanjut!",
  ui_story_31190602_70_dialog_content = "<color=#e8d9bb>Daya hisap vacuum cleaner menciptakan pusaran angin kuat di dalam ruangan.</color>",
  ui_story_31190602_71_dialog_content = "<color=#e8d9bb>Alat ini dengan cepat mulai menghisap segala sesuatu yang terlihat, termasuk lemari Bahan Eksperimental S-Grade milik Gronru.</color>",
  ui_story_31190602_72_dialog_content = "Hiss—",
  ui_story_31190602_73_dialog_content = "Graaaaaaahh!!",
  ui_story_31190602_74_dialog_content = "Apa yang dilakukan Eclipsite di sini?!",
  ui_story_31190602_75_dialog_content = "Terus merekam! Ini adalah bagian terpenting!",
  ui_story_31190602_76_dialog_content = "Apakah kamu serius?!",
  ui_story_31190602_77_option_content = "Langsung Revy",
  ui_story_31190602_78_dialog_content = "Revy! Sekarang saatnya menggunakan Eclipsite Vacuum Cleaner dengan baik!",
  ui_story_31190602_79_dialog_content = "Buatlah dia merasakan rasa sakit dan keputusasaan yang baru saja kurasakan!",
  ui_story_31190602_80_option_content = "Bersembunyi di belakang Revy",
  ui_story_31190602_81_dialog_content = "Eclipsite itu... Dia langsung menuju ke arah kita!",
  ui_story_31190602_82_dialog_content = "Ahhh—!",
  ui_story_31190602_83_dialog_content = "Sial! Sebanyak yang ingin aku bertarung, aku harus menyerahkan ini kepada Revy.",
  ui_story_31190602_84_dialog_content = "Sumber daya listriknya bagus, dan begitu juga sudutnya. Mengaktifkan Penyedot Debu Eclipsite!",
  ui_story_31190602_85_dialog_content = "Aku akan melindungimu, PlayerName!",
  ui_story_31190602_86_dialog_content = "???",
  ui_story_31190602_87_dialog_content = "Hiss—",
  ui_story_31190602_88_dialog_content = "Berhenti melawan, Eclipsite yang menjijikkan!",
  ui_story_31190602_89_dialog_content = "Revy! Turunkan sudutnya lima belas derajat dan bidik kakinya, agar ia kehilangan keseimbangan!",
  ui_story_31190602_90_dialog_content = "Sejarahmu berakhir, Eclipsite!",
  ui_story_31190602_91_dialog_content = "Graaaaaah—",
  ui_story_31190602_92_dialog_content = "Dan begitu, pahlawan muda kita melindungi orang yang paling penting baginya.",
  ui_story_31190602_93_dialog_content = "Bahkan Eclipsite yang mengancam sekalipun hanyalah sebutir debu ketika berhadapan dengan kekuatan pembersihan Eclipsite Vacuum Cleaner.",
  ui_story_31190602_94_dialog_content = "Apakah Anda bermimpi menjadi pahlawan di mata orang lain? Apakah Anda ingin melindungi orang-orang yang Anda cintai dan mengalahkan Eclipsites dengan mudah?",
  ui_story_31190602_95_dialog_content = "Lalu ambil telepon sekarang juga, hubungi hotline Laboratorium Penelitian Illumina, dan pesan milik Anda hari ini!",
  ui_story_31190602_96_dialog_content = "Pembersih Vacuum Eclipsite, tidak ada yang bisa menolaknya setelah menggunakannya.",
  ui_story_31190602_97_dialog_content = "Percayakan pada Penyedot Debu Eclipsite untuk menyelesaikan pekerjaan.",
  ui_story_31190602_98_dialog_content = "Harap dicatat: pesanan hanya dapat dilakukan antara pukul 3 sore dan 4 sore, karena Gronru sibuk bermain game di waktu lainnya.",
  ui_story_31190602_99_dialog_content = "Memotong—!",
  ui_story_31190602_100_dialog_content = "Itu sempurna! Saya akan menghubungi lab sekarang juga jika melihat ini!",
  ui_story_31190602_101_dialog_content = "Tidak setujukah kamu, Siobhan?",
  ui_story_31190602_102_dialog_content = "Um... Ya!",
  ui_story_31190602_103_dialog_content = "Fiuh... Aku kalah.",
  ui_story_31190602_104_dialog_content = "Sekarang Main Quest sudah selesai, saatnya untuk Side Quest!",
  ui_story_31190602_105_dialog_content = "Ayo kita ambil beberapa foto promosi!",
  ui_story_31190602_106_dialog_content = "Sebelum kita melanjutkan, bisakah kita membahas tentang Eclipsite tadi?! Apa yang sedang dilakukan di laboratoriummu?!",
  ui_story_31190602_107_dialog_content = "Saya membutuhkan sesuatu untuk membuat penampilan Anda lebih realistis, jadi saya menyewa beberapa orang untuk menangkapnya untuk saya.",
  ui_story_31190602_108_dialog_content = "Luar biasa, 'kan? Penemuanku sangat hebat sehingga aku harus mengajukan paten.",
  ui_story_31190602_109_dialog_content = "Aku mau satu! Berapa harganya?",
  ui_story_31190602_110_dialog_content = "Hah? J-Jangan bilang kamu benar-benar suka hal ini, Revy?!",
  ui_story_31190602_112_dialog_content = "Ini akan membuat menghajar Eclipsite jadi lebih mudah, yang berarti aku akan bisa melindungimu dengan lebih baik. Itu seharusnya membuatku selangkah lebih dekat untuk menjadi pahlawan sejati!",
  ui_story_31190602_113_dialog_content = "Biasanya, aku akan menagihmu untuk ini, tapi aku akan membuat pengecualian kali ini.",
  ui_story_31190602_114_dialog_content = "Pastikan kamu melakukan promosi yang baik untuk Penyedot Debu Eclipsite-ku, Revy!",
  ui_story_31190602_115_dialog_content = "Serahkan padaku."
}
return config
